const msg        = $input.item.json.mensaje_raw || '';
const foto_id    = $input.item.json.foto_file_id || '';
const admin_id   = $vars.USER_ID_TELEGRAM;
const from_id    = String($input.item.json.from_id);
const es_admin   = from_id === admin_id;
const is_callback = $input.item.json.is_callback || false;

let comando  = 'mensaje_libre';
let argumento = msg;

// Foto recibida sin comando -> entrar al flujo de redimensionar
if (!is_callback && foto_id && !msg.startsWith('/')) {
  comando   = 'redimensionar';
  argumento = foto_id;
}

// Callbacks de botones inline — vienen como "cmd:argumento" o solo "cmd"
if (is_callback) {
  const parts = msg.split(':');
  comando   = parts[0] || 'ayuda';
  argumento = parts.slice(1).join(':').trim();
} else if (msg.startsWith('/instruccion_off')) {
  comando   = 'instruccion_off';
  argumento = msg.replace('/instruccion_off', '').trim();
} else if (msg.startsWith('/instruccion')) {
  comando   = 'instruccion';
  argumento = msg.replace('/instruccion', '').trim();
} else if (msg.startsWith('/avatar')) {
  comando   = 'avatar';
  argumento = msg.replace('/avatar', '').trim();
} else if (msg.startsWith('/post')) {
  comando   = 'post';
  argumento = msg.replace('/post', '').trim();
} else if (msg.startsWith('/historial')) {
  comando   = 'historial';
  argumento = msg.replace('/historial', '').trim() || '5';
} else if (msg.startsWith('/aprobar')) {
  comando   = 'aprobar';
  argumento = msg.replace('/aprobar', '').trim();
} else if (msg.startsWith('/rechazar')) {
  comando   = 'rechazar';
  argumento = msg.replace('/rechazar', '').trim();
} else if (msg.startsWith('/editar')) {
  comando   = 'editar';
  argumento = msg.replace('/editar', '').trim();
} else if (msg.startsWith('/publicar')) {
  comando   = 'publicar';
  argumento = msg.replace('/publicar', '').trim();
} else if (msg.startsWith('/tendencias_yt')) {
  comando = 'tendencias_yt';
  argumento = '';
} else if (msg.startsWith('/tendencias')) {
  comando = 'tendencias';
  argumento = '';
} else if (msg.startsWith('/nuevo_avatar')) {
  comando = 'nuevo_avatar';
  argumento = '';
} else if (msg.startsWith('/entrenar_lora')) {
  comando = 'entrenar_lora';
  argumento = '';
} else if (msg.startsWith('/estado_lora')) {
  comando = 'estado_lora';
  argumento = '';
} else if (msg.startsWith('/ayuda') || msg === '/start') {
  comando   = 'ayuda';
  argumento = '';
}

return [{ json: { ...$input.item.json, comando, argumento, es_admin } }];

const configItems = $input.all();
const base = $('Restaurar contexto comando').item.json;
const avatar_id = configItems[0]?.json?.valor || 'sofia_01';
return [{ json: { ...base, avatar_id } }];

const item = $input.item.json;
const argumento = item.argumento || '';
if (!argumento) {
  return [{ json: { ...item, error: 'vacio', nueva_instruccion: { id: '', instruccion: '' } } }];
}
const id = 'inst_' + Date.now();
return [{ json: {
  ...item,
  nueva_instruccion: {
    id,
    avatar_id: item.avatar_id,
    fecha: item.fecha,
    hora: item.hora,
    instruccion: argumento,
    activa: 'SI',
    prioridad: 'media',
    origen: 'admin_telegram'
  }
} }];

