parameters.jsCode:
const perfilItems = $('Leer perfil del avatar').all();
const instrItems  = $('Leer instrucciones activas').all();
const histItems   = $('Leer ultimos posts').all();
const base        = $('Extraer avatar activo').item.json;
const avatar_id   = base.avatar_id;

const perfil = perfilItems.find(i => i.json.avatar_id === avatar_id)?.json || perfilItems[0]?.json || {};

// Instrucciones de contenido/tono/formato/restriccion (NO imagen)
const instrActivas = instrItems.filter(i =>
  i.json.activa === 'SI' &&
  i.json.avatar_id === avatar_id &&
  i.json.tema !== 'imagen'
);

const instrTexto = instrActivas.length > 0
  ? instrActivas.map(i => '- ' + i.json.instruccion).join('\n')
  : '(sin instrucciones especiales aun)';

const instruccionesUsadas = instrActivas.map(i => i.json.id).join(', ');

const ultimosPosts = histItems.slice(-5).reverse();
const histTexto = ultimosPosts.length > 0
  ? ultimosPosts.map(i => '- ' + String(i.json.texto || '').slice(0, 80)).join('\n')
  : '(sin posts previos)';

const partes     = String(base.argumento || '').split(' ');
const red_social = partes[0] || 'instagram';
const tema       = partes.slice(1).join(' ') || 'libre';

function tipoContenido(red) {
  if (red === 'instagram') return 'caption para post de Instagram';
  if (red === 'tiktok')    return 'descripcion para TikTok';
  if (red === 'historia')  return 'texto para historia de Instagram';
  return 'post';
}

const system_prompt = 'Eres un experto creador de contenido para redes sociales de influencers virtuales. Generas contenido autentico, natural y humano que parece escrito por una persona real.';

const user_prompt = `PERFIL DEL AVATAR:
Nombre: ${perfil.nombre || ''}
Edad: ${perfil.edad || ''}
Ciudad: ${perfil.ciudad || ''}
Bio: ${perfil.bio || ''}
Tono de voz: ${perfil.tono_voz || ''}
Intereses: ${perfil.intereses || ''}
Ejemplos de su forma de hablar (SOLO para captar el estilo, NO los copies literalmente ni los fuerces): ${perfil.frases_tipicas || ''}
Lo que nunca hace: ${perfil.lo_que_nunca_dice || ''}

PAUTAS DEL PERSONAJE (integralas con naturalidad, no como lista de requisitos a cumplir):
${instrTexto}

ULTIMOS POSTS (para no repetir estilo ni tema):
${histTexto}

TAREA: Genera un ${tipoContenido(red_social)} para ${red_social} sobre el tema: "${tema}".

REQUISITOS:
- Debe sonar completamente natural, como si lo escribiera una persona real
- Maximo 3-5 hashtags muy especificos al final si aplica
- Tono acorde al perfil
- Longitud apropiada para ${red_social}
- Incluye emojis naturales, no exagerados
- Escribe como un mensaje espontaneo de redes, NO como un anuncio publicitario
- Evita sonar perfecto o demasiado estructurado; las personas reales divagan un poco
- No fuerces las frases tipicas ni las pautas: deben fluir naturalmente o no aparecer
- Varia el inicio; no empieces siempre igual
- NO menciones que eres IA

Devuelve SOLO el texto del post, sin explicaciones ni comillas externas.`;

return [{ json: {
  chat_id: base.chat_id,
  avatar_id,
  perfil,
  instrItems_all: instrItems.map(i => i.json),
  red_social,
  tema,
  perfil_nombre: perfil.nombre || '',
  instrucciones_usadas: instruccionesUsadas,
  system_prompt,
  user_prompt
} }];

const resp     = $input.item.json;
const anterior = $('Construir prompt del agente').item.json;

const texto = resp.choices?.[0]?.message?.content?.trim() || 'Error al generar el post';
const post_id = 'post_' + Date.now();

return [{ json: {
  chat_id:              anterior.chat_id,
  avatar_id:            anterior.avatar_id,
  perfil:               anterior.perfil,
  instrItems_all:       anterior.instrItems_all,
  red_social:           anterior.red_social,
  tema:                 anterior.tema,
  perfil_nombre:        anterior.perfil_nombre,
  instrucciones_usadas: anterior.instrucciones_usadas,
  texto_generado:       texto,
  post_id,
  fecha: new Date().toISOString().slice(0,10),
  hora:  new Date().toISOString().slice(0,16).replace('T',' ')
} }];

const anterior = $('Extraer texto generado').item.json;
const perfil = anterior.perfil || {};
const avatar_id = anterior.avatar_id;
const instrItems_all = anterior.instrItems_all || [];

// Instrucciones de imagen activas (escena/estilo, NO identidad)
const instrImg = instrItems_all.filter(i =>
  i.activa === 'SI' && i.avatar_id === avatar_id && i.tema === 'imagen'
);
const instrImgTexto = instrImg.length > 0
  ? instrImg.map(i => '- ' + i.instruccion).join('\n')
  : '(sin instrucciones especiales de imagen)';

// SOLO estilo visual (estetica). La identidad NO se describe: viene de las 3 fotos.
const img_estilo = perfil.img_prompt_estilo || 'realistic candid lifestyle photo, natural lighting';

// Groq genera UNICAMENTE la escena/accion/ambiente a partir del post. No describe a la persona.
const user_prompt = `Eres experto en componer escenas para generacion de imagenes con IA.

A partir del siguiente post de redes sociales, describe SOLO la ESCENA donde estaria el personaje: el lugar, la accion que realiza, el ambiente, la hora del dia y el encuadre. NO describas el rostro, el cuerpo, el color de pelo, la piel, ni ningun rasgo fisico de la persona (eso lo aportan las fotos de referencia, no el texto).

ESTILO VISUAL deseado: ${img_estilo}

INSTRUCCIONES DE IMAGEN (escena/estilo):
${instrImgTexto}

POST:
'${anterior.texto_generado}'

Devuelve en INGLES, maximo 50 palabras, SOLO la descripcion de la escena y el estilo (lugar, accion, ambiente, luz, encuadre). Sin mencionar rasgos de la persona. Sin explicaciones.`;

return [{ json: { ...anterior, user_prompt_imagen: user_prompt } }];

const respGroq = $input.item.json;
const anterior = $('Construir prompt de imagen').item.json;

// Escena/estilo que genero Groq (sin rasgos de la persona)
const escena = respGroq.choices?.[0]?.message?.content?.trim()
  || (anterior.perfil?.img_prompt_estilo || 'realistic candid lifestyle photo, natural lighting');

// La IDENTIDAD viene de las 3 fotos de referencia adjuntas, NO del texto.
// Instruccion imperativa y prioritaria al inicio del prompt.
const IDENTIDAD = 'The person in this image MUST be identical to the same person shown in the attached reference images. Carefully observe the reference images and reproduce that person EXACTLY as they actually appear. Do NOT invent, add or remove any feature. Some people have distinctive traits such as vitiligo patches, heterochromia or differently colored eyes, hazel eyes, freckles, a tooth gap, moles or birthmarks — ONLY include such a trait if it is clearly visible in the reference images, and if so reproduce it faithfully with the same shape, color and location. If a trait is NOT present in the references, do NOT add it. Preserve their face, facial structure, skin tone and all real distinctive features exactly as in the references — do not alter, stylize, multiply or move anything. Only place this exact, unchanged person into the scene described below.';

const promptImagen = `${IDENTIDAD}\n\nSCENE AND STYLE: ${escena}`;

return [{ json: {
  ...anterior,
  prompt_imagen: promptImagen
} }];

const j = $('Extraer texto generado').item.json;
const token = $vars.TELEGRAM_BOT_TOKEN;
const cabecera = '📱 ' + (j.red_social||'').toUpperCase() + ' — ' + j.perfil_nombre;
const texto = cabecera + '\n\n' + j.texto_generado + '\n\n🆔 ' + j.post_id;
const reply_markup = JSON.stringify({
  inline_keyboard: [
    [{ text: '✅ Aprobar',  callback_data: 'aprobar:'  + j.post_id }],
    [{ text: '✏️ Editar',   callback_data: 'editar:'   + j.post_id }],
    [{ text: '❌ Rechazar', callback_data: 'rechazar:' + j.post_id }]
  ]
});
const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${token}/sendMessage`,
  body: { chat_id: j.chat_id, text: texto, reply_markup },
  json: true
});
return [{ json: { ok: resp.ok, post_id: j.post_id } }];

const items    = $input.all();
const base     = $('Restaurar contexto comando').item.json;
const cantidad = parseInt(base.argumento) || 5;
const ultimos  = items.slice(-cantidad).reverse();

if (ultimos.length === 0) {
  return [{ json: { chat_id: base.chat_id, texto_respuesta: 'No hay posts en el historial todavia.' } }];
}

const lineas = ultimos.map((item, i) => {
  const p = item.json;
  return `${i+1}. [${p.estado || 'borrador'}] ${p.avatar_id || ''} — ${p.red_social || ''} — ${p.fecha_creacion || ''}\n${String(p.texto || '').slice(0,80)}...`;
});

return [{ json: { chat_id: base.chat_id, texto_respuesta: 'Ultimos ' + ultimos.length + ' posts:\n\n' + lineas.join('\n\n') } }];

