parameters.jsCode:
const campana = $('Extraer datos de campana').item.json;
const b = campana.brand;

function driveUrl(url) {
  if (!url || !url.trim()) return '';
  const m = url.match(/\/file\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m ? `https://drive.google.com/uc?export=download&confirm=t&id=${m[1]}` : url.trim();
}

const prompt = `${b.BRAND_NAME}. Act as a Social Media Art Director and Digital Collage Artist specializing in bold, youth-oriented brand content for Instagram and digital campaigns.
Create a dynamic digital collage featuring ${b.MODEL_DESCRIPTION} drinking a cold ${b.PRODUCT_NAME} with dramatic soda splashes and carbonation effects exploding around the composition.
The model should look ${b.MODEL_ATTITUDE}.
The background should feature ${b.BACKGROUND_STYLE} mixed with abstract street-style collage elements.
Use bold ${b.PRIMARY_COLORS} color blocking inspired by ${b.BRAND_NAME} branding.
Add hand-painted brush strokes, ripped paper textures, graffiti graphics, spray paint effects, bold abstract shapes, layered paper collage effects, dynamic typography, grain, noise texture, and handcrafted imperfections.
The composition should feel ${b.MOOD}.
The model must be positioned ${b.MODEL_POSITION} while ${b.MODEL_ACTION} naturally.
Typography text: "${b.SLOGAN}"
PHASE 1: CONCEPTUAL FRAMEWORK — dynamic digital collage merging fashion photography with graphic design chaos.
PHASE 2: COLOR BLOCKING — Large organic shape 40-60% in bold ${b.PRIMARY_COLORS} behind model.
PHASE 3: GRAPHIC ELEMENTS — 3-5 abstract graphic elements scattered asymmetrically.
PHASE 4: TEXTURE BACKGROUND — off-white textured background blended with ${b.BACKGROUND_STYLE}.
PHASE 5: COMPOSITION — Asymmetric balance, 15-20% negative space, diagonal energy.
TECHNICAL: Aspect Ratio ${b.ASPECT_RATIO}, ${b.RESOLUTION}, sRGB vibrant. Camera: ${b.CAMERA_ANGLE}. Lighting: ${b.LIGHTING_STYLE}. Typography: ${b.TYPOGRAPHY_STYLE}. Energy: ${b.ENERGY_LEVEL}. Audience: ${b.TARGET_AUDIENCE}. Collage: ${b.COLLAGE_INTENSITY}.
First and second attached images: exact face and body reference of the model from different angles — preserve facial identity and body accurately.
Third attached image: exact product reference — preserve label and design accurately.
Fourth attached image: exact logo reference — do not modify logo design.`;

const base = {
  chat_id:       campana.chat_id,
  brand_name:    b.BRAND_NAME,
  prompt_banner: prompt
};

// Emitir hasta 4 items — omitir si el link está vacío
const slots = [
  { img_slot: 'modelo1',   img_url: driveUrl(b.MODEL_IMAGE_DRIVE_LINK) },
  { img_slot: 'modelo2',   img_url: driveUrl(b.MODEL2_IMAGE_DRIVE_LINK || '') },
  { img_slot: 'producto',  img_url: driveUrl(b.PRODUCT_IMAGE_DRIVE_LINK) },
  { img_slot: 'logo',      img_url: driveUrl(b.LOGO_IMAGE_DRIVE_LINK) },
];

return slots
  .filter(s => s.img_url !== '')
  .map(s => ({ json: { ...base, ...s } }));

const b64 = $json.data?.[0]?.b64_json;
if (!b64) throw new Error('Sin b64_json de OpenAI: ' + JSON.stringify($json).substring(0,500));

const buf = Buffer.from(b64, 'base64');
const binaryData = await this.helpers.prepareBinaryData(buf, 'banner.png', 'image/png');

// Leer chat_id y brand_name del nodo de preparación de items
const itemBase = $('Preparar 3 items de imagen').first().json;

return [{
  json: {
    chat_id:    itemBase.chat_id    || '',
    brand_name: itemBase.brand_name || '',
  },
  binary: { data: binaryData }
}];

const base = $('Detectar comando').item.json;
let comando   = base.comando;
let argumento = base.argumento;
const is_callback = base.is_callback || false;
const msg = base.mensaje_raw || '';

// Leer estado pendiente del config
const estadoItems = $input.all();
const estadoRow = estadoItems.find(i => i.json.clave === 'estado_pendiente');
const estadoValor = estadoRow?.json?.valor || '';

// ===== NUEVO AVATAR (v7) =====
const constrRow = estadoItems.find(i => i.json.clave === 'avatar_en_construccion');
const constrValor = constrRow?.json?.valor || '';
let _constr = null;
try { _constr = constrValor ? JSON.parse(constrValor) : null; } catch(e) { _constr = null; }

if (comando === 'nuevo_avatar') {
  return [{ json: { ...base, comando:'nuevo_avatar', accion:'ejecutar', na_paso:'inicio' } }];
}
if (comando === 'estado_lora') {
  return [{ json: { ...base, comando:'estado_lora', accion:'ejecutar' } }];
}
  if (comando === 'entrenar_lora') {
  return [{ json: { ...base, comando:'entrenar_lora', accion:'ejecutar' } }];
}
if (comando === 'lora' && is_callback) {
  return [{ json: { ...base, comando:'lora', accion:'ejecutar', avatar_id: argumento } }];
}
if (_constr && is_callback && comando === 'genavt') {
  return [{ json: { ...base, comando:'nuevo_avatar', accion:'ejecutar', na_paso:'genero', na_constr:JSON.stringify(_constr), na_texto:argumento } }];
}
if (_constr && !msg.startsWith('/') && !is_callback) {
  if (base.foto_file_id) {
    return [{ json: { ...base, comando:'nuevo_avatar', accion:'ejecutar', na_paso:'foto', na_constr:JSON.stringify(_constr), foto_file_id:base.foto_file_id } }];
  }
  return [{ json: { ...base, comando:'nuevo_avatar', accion:'ejecutar', na_paso:(_constr.paso||'nombre'), na_constr:JSON.stringify(_constr), na_texto:msg.trim() } }];
}
// ===== FIN NUEVO AVATAR =====


// Comandos que requieren argumento obligatorio
const requierenArg = {
  'editar':          { pregunta: '✏️ Escribe el nuevo texto para la publicación:', botones: null },
  'instruccion':     { pregunta: '💡 Escribe la instrucción que quieres enseñarle al avatar:', botones: null },
  'instruccion_off': { pregunta: '🔕 Selecciona la instrucción a desactivar:', botones: 'instrucciones' },
  'avatar':          { pregunta: '🎭 ¿Qué avatar quieres activar?', botones: 'avatares' },
  'publicar':        { pregunta: '🎨 ¿Para qué marca generamos el banner?', botones: 'marcas' },
  'post':            { pregunta: '📱 Escribe el tema del post (ej: outfit de verano):', botones: null }
};

// Post necesita red + tema. Si solo trae la red (1 palabra), pedir el tema.
function postFaltaTema(cmd, arg) {
  if (cmd !== 'post') return false;
  const partes = (arg || '').trim().split(/\s+/).filter(Boolean);
  return partes.length < 2; // menos de 2 palabras = falta el tema
}

// ── CASO AYUDA_REDIM: el usuario pulsó el botón del menú; pedir que envíe la foto ──
if (comando === 'ayuda_redim') {
  return [{ json: {
    ...base,
    comando: 'ayuda_redim',
    argumento: '',
    accion: 'ejecutar',
    limpiar_estado: estadoValor ? true : false
  } }];
}

// ── CASO REDIM: el usuario subió una foto → guardar file_id y pedir dimensión ──
if (comando === 'redimensionar' && !is_callback) {
  return [{ json: {
    ...base,
    comando: 'redimensionar',
    accion: 'pedir',
    pedir_pregunta: '📐 ¿A qué proporción quieres adaptar el diseño? Se conservarán TODOS los elementos, reubicados al nuevo formato:',
    pedir_botones: 'dimensiones',
    estado_guardar: 'redim|' + argumento   // guarda redim|<foto_file_id>
  } }];
}

// ── CASO REDIM CALLBACK: el usuario eligió la dimensión (redim:WxH) ──
if (comando === 'redim' && is_callback) {
  const [cmdPendiente, fotoGuardada] = (estadoValor || '').split('|');
  // argumento del callback = 'WxH' (la dimensión); foto viene del estado pendiente
  return [{ json: {
    ...base,
    comando: 'redim',
    argumento: argumento,        // dimensión elegida, ej "1024x1536"
    foto_file_id: fotoGuardada || '',
    accion: 'ejecutar',
    limpiar_estado: true
  } }];
}

// ── CASO EDITAR (botón ✏️): el callback trae el post_id → pedir el texto nuevo ──
if (comando === 'editar' && is_callback) {
  return [{ json: {
    ...base,
    comando: 'editar',
    accion: 'pedir',
    pedir_pregunta: '✏️ Escribe el nuevo texto para la publicación ' + argumento + ':',
    pedir_botones: '',
    estado_guardar: 'editar|' + argumento   // guarda editar|<post_id>
  } }];
}

// ── CASO 1: Hay estado pendiente y el usuario mandó texto libre (no comando, no callback) ──
const esComandoNuevo = msg.startsWith('/') || is_callback;
if (estadoValor && !esComandoNuevo) {
  const [cmdPendiente, extra] = estadoValor.split('|');
  comando = cmdPendiente;
  // Combinar extra (si existe) con el texto nuevo
  argumento = extra ? (extra + ' ' + msg).trim() : msg.trim();

  return [{ json: {
    ...base,
    comando,
    argumento,
    accion: 'ejecutar',
    limpiar_estado: true
  } }];
}

// ── CASO 2: Comando nuevo que requiere argumento pero llegó vacío ──
if (requierenArg[comando] && ((!argumento || argumento.trim() === '') || postFaltaTema(comando, argumento))) {
  // Caso especial post: si el callback trae "instagram libre" o similar, igual pedir tema
  const cfg = requierenArg[comando];

  // post desde botón trae la red ya, pero necesita tema → guardar "post|instagram"
  let extraGuardar = '';
  if (comando === 'post' && argumento && argumento.trim() !== '') {
    extraGuardar = argumento.trim().split(' ')[0]; // la red social
  }

  return [{ json: {
    ...base,
    comando,
    accion: 'pedir',
    pedir_pregunta: cfg.pregunta,
    pedir_botones: cfg.botones || '',
    estado_guardar: comando + '|' + extraGuardar
  } }];
}

// ── CASO 3: Comando normal con argumento, o comando sin requisito ──
return [{ json: {
  ...base,
  comando,
  argumento,
  accion: 'ejecutar',
  limpiar_estado: estadoValor ? true : false
} }];

