const ri = $('Resolver intencion').item.json;
const paso = ri.na_paso || 'inicio';
const texto = ri.na_texto || '';
const fotoId = ri.foto_file_id || '';
const hora = ri.hora;
const chat_id = ri.chat_id;
let constr = {};
try { constr = ri.na_constr ? JSON.parse(ri.na_constr) : {}; } catch(e) { constr = {}; }
function esc(s){ return String(s||'').replace(/([_*\[\]()~`>#+\-=|{}.!])/g,'\\$1'); }
function sanit(s){ return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9-_]/g,'_').replace(/_+/g,'_').replace(/^_|_$/g,''); }

let pregunta='', botones=null, finalizar=false;

if (paso === 'inicio') {
  constr = { paso:'nombre', fotos:[] };
  pregunta = '🆕 *Nuevo avatar*\nPaso 1/4 — Escribe el *nombre* (sin espacios ni símbolos, ej: Luna_Vega):';
} else if (paso === 'nombre') {
  const ln = sanit(texto);
  if (!ln || ln.length < 2) { pregunta='⚠️ Nombre inválido. Usa letras, números, - o _ (ej: Luna_Vega):'; constr.paso='nombre'; }
  else { constr.nombre=texto; constr.lora_nombre=ln; constr.paso='genero';
    pregunta=`✅ Nombre: *${esc(texto)}*\nPaso 2/4 — Selecciona el *género*:`;
    botones={inline_keyboard:[
      [{text:'♀️ Female',callback_data:'genavt:female'},{text:'♂️ Male',callback_data:'genavt:male'}],
      [{text:'⚧ Neutral',callback_data:'genavt:neutral'},{text:'✳️ Custom',callback_data:'genavt:custom'}]]};
  }
} else if (paso === 'genero') {
  const g = ['male','female','neutral','custom'].includes(texto)?texto:'neutral';
  constr.genero=g; constr.paso='descripcion';
  pregunta=`✅ Género: *${esc(g)}*\nPaso 3/4 — Escribe una *descripción* corta (apariencia, estilo, personalidad):`;
} else if (paso === 'descripcion') {
  constr.descripcion=texto; constr.paso='fotos';
  pregunta='✅ Descripción guardada.\nPaso 4/4 — Envíame entre *8 y 20 fotos*, una por una 📸\nCuando termines, escribe *listo*.';
} else if (paso === 'fotos' || paso === 'foto') {
  constr.fotos = constr.fotos||[];
  if (fotoId) {
    if (constr.fotos.length>=20) pregunta='⚠️ Ya tienes 20 fotos (máximo). Escribe *listo*.';
    else { constr.fotos.push(fotoId);
      pregunta=`📸 Foto ${constr.fotos.length}/20 recibida.`+(constr.fotos.length>=8?' Envía más o escribe *listo*.':` Faltan ${8-constr.fotos.length} para el mínimo.`); }
    constr.paso='fotos';
  } else if (/^listo$/i.test(texto)) {
    const n=constr.fotos.length;
    if (n<8){ pregunta=`⚠️ Solo llevas ${n} fotos. Mínimo 8. Envía ${8-n} más y escribe *listo*.`; constr.paso='fotos'; }
    else { finalizar=true; pregunta=`⏳ Procesando ${n} fotos y creando *${esc(constr.nombre)}*...`; }
  } else { pregunta='📸 Envíame una foto, o escribe *listo* (mín. 8).'; constr.paso='fotos'; }
}

return [{ json: {
  chat_id, hora, pregunta,
  botones: botones?JSON.stringify(botones):'',
  finalizar,
  valorGuardar: JSON.stringify(constr),
  nombre:constr.nombre||'', lora_nombre:constr.lora_nombre||'',
  genero:constr.genero||'', descripcion:constr.descripcion||'',
