catch (e) { resp = await this.helpers.httpRequest({ method:'POST', url, body:base, json:true }); }
return [{ json: { ok: resp.ok } }];

const j = $('NA Procesar paso').item.json;
const carpeta_id = $('NA Crear carpeta avatar').item.json.id || '';
const token = $vars.TELEGRAM_BOT_TOKEN;
const fotos = j.fotos || [];
const out = [];
for (let i=0;i<fotos.length;i++){
  // getFile para obtener file_path
  const gf = await this.helpers.httpRequest({ method:'GET', url:`https://api.telegram.org/bot${token}/getFile?file_id=${fotos[i]}`, json:true });
