} }];

const j=$('NA Juntar fotos').item.json;
const token=$vars.TELEGRAM_BOT_TOKEN;
const txt=`✅ Avatar *${j.nombre}* creado con ${j.total} fotos.\n`+
  `• Guardado en perfil_avatar (estado LoRA: pendiente)\n`+
  `• Las 3 primeras fotos quedaron como referencia para /post\n\n`+
  `Para entrenar su LoRA en Magnific, usa /entrenar_lora`;
await this.helpers.httpRequest({method:'POST',url:`https://api.telegram.org/bot${token}/sendMessage`,
  body:{chat_id:j.chat_id,text:txt,parse_mode:'Markdown'},json:true});
return [{json:{ok:true}}];

const base=$('Resolver intencion').item.json;
const rows=$input.all().map(i=>i.json);
const entrenables=rows.filter(a=>a.avatar_id && (!a.lora_estado || a.lora_estado==='pendiente'));
const token=$vars.TELEGRAM_BOT_TOKEN;
let text, reply_markup;
if(!entrenables.length){
  text='ℹ️ No hay avatares pendientes de entrenar. Crea uno con /nuevo_avatar.';
  reply_markup={inline_keyboard:[[{text:'🆕 Nuevo avatar',callback_data:'nuevo_avatar'}]]};
}else{
