  reply_markup={inline_keyboard:entrenables.map(a=>[{text:`🎭 ${a.nombre||a.avatar_id}`,callback_data:`lora:${a.avatar_id}`}])};
}
const resp=await this.helpers.httpRequest({method:'POST',url:`https://api.telegram.org/bot${token}/sendMessage`,
