return [{json:{ok:resp.ok}}];

const base=$('Resolver intencion').item.json;
const a=$input.first().json;
if(!a||!a.avatar_id) throw new Error('Avatar no encontrado: '+base.avatar_id);
if(a.lora_estado==='entrenando') throw new Error('Ese avatar ya se está entrenando.');
if(a.lora_estado==='entrenado') throw new Error('Ese avatar ya tiene LoRA entrenado.');
const urls=(a.urls_fotos||'').split(',').map(s=>s.trim()).filter(Boolean);
if(urls.length<8) throw new Error(`El avatar tiene ${urls.length} fotos; Magnific requiere mínimo 8.`);
const gen=['male','female','neutral','custom'].includes(a.genero)?a.genero:'neutral';

// Truncado inteligente de la descripción a 255 caracteres (límite de Magnific)
function truncar(txt, max=255){
  txt=String(txt||'').trim();
  if(txt.length<=max) return txt;
  let corte=txt.slice(0,max);
  // cortar en el último punto, o si no hay, en el último espacio
  const punto=corte.lastIndexOf('.');
  const espacio=corte.lastIndexOf(' ');
  if(punto>180) corte=corte.slice(0,punto+1);
  else if(espacio>180) corte=corte.slice(0,espacio);
  return corte.trim();
}

return [{json:{
  avatar_id:a.avatar_id,
  chat_id:base.chat_id, hora:base.hora,
  body:{
    name:a.lora_nombre||a.avatar_id,
    description:truncar(a.descripcion, 255),
    quality:'high',
    gender:gen,
    images:urls.slice(0,20),
    webhook_url:$vars.MAGNIFIC_WEBHOOK_URL
  }
}}];

const p=$('EL Payload').item.json;
