const tid=resp.data?.task_id||'(sin id)';
const txt=`🧬 Entrenamiento iniciado para *${p.avatar_id}*.\nTask: \`${tid}\`\nTe aviso por aquí cuando el LoRA esté listo. ⏳`;
await this.helpers.httpRequest({method:'POST',url:`https://api.telegram.org/bot${token}/sendMessage`,
  body:{chat_id:p.chat_id,text:txt,parse_mode:'Markdown'},json:true});
return [{json:{ok:true}}];

const base=$('Resolver intencion').item.json;
const resp=$('SL Consultar loras').first().json;
const rows=$('SL Leer avatares').all().map(i=>i.json);

// LoRAs entrenados en Magnific (customs + default por si acaso)
const data=resp.data||{};
const loras=[...(data.customs||[]), ...(data.default||[])];

// Avatares que esperamos (estado entrenando)
const enEntrenamiento=rows.filter(a=>a.avatar_id && a.lora_estado==='entrenando');

const actualizar=[];   // {avatar_id, nombre}
const aunEntrenando=[];
for(const a of enEntrenamiento){
  const nombreLora=a.lora_nombre||a.avatar_id;
  const match=loras.find(l=>l.name===nombreLora && (l.type==='character'||!l.type));
  const completo=match && match.training && (match.training.status==='completed' || match.training.status==='COMPLETED');
  if(completo) actualizar.push({avatar_id:a.avatar_id, nombre:a.nombre||a.avatar_id, lora_real_id:String(match.id||'')});
  else aunEntrenando.push(a.nombre||a.avatar_id);
}

return [{ json: {
  chat_id: base.chat_id, hora: base.hora,
  hay_actualizar: actualizar.length>0,
  actualizar,
  aunEntrenando,
  total_entrenando: enEntrenamiento.length
} }];

const j=$('SL Emparejar').item.json;
const out=[];
for(const a of (j.actualizar||[])){
  out.push({ json:{ avatar_id:a.avatar_id, nombre:a.nombre, lora_real_id:a.lora_real_id, hora:j.hora } });
}
if(out.length===0){ return [{ json:{ _vacio:true } }]; }
return out;

const j=$('SL Emparejar').item.json;
const token=$vars.TELEGRAM_BOT_TOKEN;
const url=`https://api.telegram.org/bot${token}/sendMessage`;
function esc(s){ return String(s||'').replace(/([_*\[\]()~`>#+\-=|{}.!])/g,'\\$1'); }
let txt;
if(j.total_entrenando===0){
  txt='ℹ️ No tienes avatares en estado *entrenando* ahora mismo.';
} else if(j.hay_actualizar){
  const nombres=(j.actualizar||[]).map(a=>'• '+esc(a.nombre)).join('\n');
  txt=`✅ Estos LoRAs ya están *listos* y los marqué como entrenados:\n${nombres}`;
  if((j.aunEntrenando||[]).length){
    txt+=`\n\n⏳ Aún entrenando:\n`+j.aunEntrenando.map(n=>'• '+esc(n)).join('\n');
  }
} else {
  txt=`⏳ Todavía en entrenamiento:\n`+(j.aunEntrenando||[]).map(n=>'• '+esc(n)).join('\n')+`\n\nVuelve a consultar en unos minutos con /estado_lora`;
}
try{ await this.helpers.httpRequest({method:'POST',url,body:{chat_id:j.chat_id,text:txt,parse_mode:'Markdown'},json:true}); }
catch(e){ await this.helpers.httpRequest({method:'POST',url,body:{chat_id:j.chat_id,text:txt},json:true}); }
return [{json:{ok:true}}];

// Toma la escena/estilo (prompt_imagen de 'Extraer prompt de imagen') y antepone
// el personaje LoRA de Magnific con sintaxis @nombre.
// El nombre del personaje es el MISMO con que se entreno: lora_nombre || avatar_id
// (igual que 'EL Payload' y 'SL Emparejar'). Solo se le agrega la @.
const anterior = $('Extraer prompt de imagen').item.json;
const tg       = $('Extraer texto generado').item.json;
const perfil   = tg.perfil || {};

if (perfil.lora_estado && perfil.lora_estado !== 'entrenado') {
  throw new Error(`El avatar aun no tiene LoRA entrenado (estado: ${perfil.lora_estado}). Usa /entrenar primero.`);
}

const charName = (perfil.lora_nombre || tg.avatar_id || '').toString().trim();
if (!charName) {
  throw new Error('No se pudo determinar el nombre del personaje Magnific (lora_nombre / avatar_id).');
}

// Con LoRA la identidad la aporta @nombre, NO el texto. Usamos solo la escena de Groq.
const full = anterior.prompt_imagen || '';
const idx = full.indexOf('SCENE AND STYLE:');
const escena = idx >= 0 ? full.slice(idx + 'SCENE AND STYLE:'.length).trim() : full.trim();

const promptMagnific = `@${charName} ${escena}`;

const red = (tg.red_social || '').toString().toLowerCase();
let aspect = 'social_post_4_5';
if (red.includes('historia') || red.includes('story') || red.includes('tiktok')) {
  aspect = 'social_story_9_16';
}

return [{ json: {
  chat_id: tg.chat_id,
  post_id: tg.post_id,
  prompt_magnific: promptMagnific,
  aspect_ratio: aspect,
} }];

